PRAGMA foreign_keys=ON;
CREATE TABLE address_zones ("zone_id" TEXT PRIMARY KEY, "zone_name" TEXT, "lifecycle_state" TEXT);
CREATE TABLE students ("student_id" TEXT PRIMARY KEY, "given_name" TEXT, "family_name" TEXT, "zone_id" TEXT, "address_label" TEXT, "wheelchair_required" TEXT, "lifecycle_state" TEXT);
CREATE TABLE guardian_contacts ("contact_id" TEXT PRIMARY KEY, "student_id" TEXT, "phone" TEXT, "email" TEXT, "valid" TEXT);
CREATE TABLE stops ("stop_id" TEXT PRIMARY KEY, "zone_id" TEXT, "stop_name" TEXT, "approved" TEXT, "accessible" TEXT, "latitude" TEXT, "longitude" TEXT);
CREATE TABLE buses ("bus_id" TEXT PRIMARY KEY, "capacity" TEXT, "accessible" TEXT, "lifecycle_state" TEXT);
CREATE TABLE drivers ("driver_id" TEXT PRIMARY KEY, "display_name" TEXT, "license_class" TEXT, "lifecycle_state" TEXT);
CREATE TABLE capacity_changes ("change_id" TEXT PRIMARY KEY, "bus_id" TEXT, "effective_date" TEXT, "capacity" TEXT);
CREATE TABLE routes ("route_id" TEXT PRIMARY KEY, "bus_id" TEXT, "driver_id" TEXT, "service_date" TEXT, "status" TEXT);
CREATE TABLE route_stops ("route_stop_id" TEXT PRIMARY KEY, "route_id" TEXT, "stop_id" TEXT, "sequence_no" TEXT, "arrival_minute" TEXT, "travel_from_previous_min" TEXT, "dwell_min" TEXT);
CREATE TABLE assignments ("assignment_id" TEXT PRIMARY KEY, "student_id" TEXT, "route_id" TEXT, "stop_id" TEXT, "effective_start" TEXT, "effective_end" TEXT, "status" TEXT);
CREATE TABLE route_disruptions ("disruption_id" TEXT PRIMARY KEY, "route_id" TEXT, "service_date" TEXT, "reason" TEXT, "status" TEXT);
CREATE TABLE attendance_events ("attendance_id" TEXT PRIMARY KEY, "student_id" TEXT, "service_date" TEXT, "route_id" TEXT, "status" TEXT, "ground_truth_issue" TEXT);
CREATE TABLE notifications ("notification_id" TEXT PRIMARY KEY, "student_id" TEXT, "contact_id" TEXT, "attendance_id" TEXT, "channel" TEXT, "status" TEXT, "created_at" TEXT, "message_code" TEXT);
CREATE TABLE issues ("issue_id" TEXT PRIMARY KEY, "issue_type" TEXT, "entity_id" TEXT, "expected_decision" TEXT, "details" TEXT);
